const results = [];
for (const item of $input.all()) {
  const biz = item.json;
  const rating = biz.totalScore;
  const reviews = biz.reviews || [];
  const hasNegativeReview = reviews.some(r => r.stars && r.stars <= 2);

  if (rating && rating < 3.5 && hasNegativeReview) {
    const negReview = reviews.find(r => r.stars <= 2);
    results.push({
      json: {
        name: biz.title || '',
        rating: rating,
        total_reviews: biz.reviewsCount || 0,
        address: biz.address || '',
        website: biz.website || '',
        phone: biz.phone || '',
        category: biz.categoryName || '',
        maps_url: biz.url || '',
        review_snippet: negReview?.text || '',
        review_count: reviews.length,
        latitude: biz.location?.lat || '',
        longitude: biz.location?.lng || '',
        working_hours: JSON.stringify(biz.openingHours || {}),
        place_id: biz.placeId || ''
      }
    });
  }
}
return results;

const seen = new Set();
const unique = [];
for (const item of $input.all()) {
  const id = item.json.place_id;
  if (id && !seen.has(id)) {
    seen.add(id);
    unique.push(item);
  }
}
return unique;
